parameters.functionCode:
const repo = $input.first().json.GITHUB_REPO;
const token = $input.first().json.GITHUB_TOKEN;

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = weekAgo.toISOString();
const until = now.toISOString();

const headers = token ? { 'Authorization': `token ${token}`, 'Accept': 'application/vnd.github.v3+json' } : { 'Accept': 'application/vnd.github.v3+json' };

// Fetch commits
const commitsResp = await fetch(`https://api.github.com/repos/${repo}/commits?since=${since}&until=${until}&per_page=100`, { headers });
const commits = commitsResp.ok ? await commitsResp.json() : [];

// Fetch closed issues
const issuesResp = await fetch(`https://api.github.com/repos/${repo}/issues?state=closed&since=${since}&per_page=100`, { headers });
const issues = issuesResp.ok ? await issuesResp.json() : [];

// Fetch merged PRs
const prsResp = await fetch(`https://api.github.com/repos/${repo}/pulls?state=closed&sort=updated&direction=desc&per_page=100`, { headers });
const allPrs = prsResp.ok ? await prsResp.json() : [];
const mergedPrs = allPrs.filter(pr => pr.merged_at && new Date(pr.merged_at) >= new Date(since));

return [{
  json: {
    repo,
    period: `${weekAgo.toISOString().split('T')[0]} to ${now.toISOString().split('T')[0]}`,
    commits: commits.map(c => ({
      sha: c.sha?.substring(0, 7),
      message: c.commit?.message?.split('\n')[0],
      author: c.commit?.author?.name,
      date: c.commit?.author?.date
    })),
    issues: issues.map(i => ({
      number: i.number,
      title: i.title,
      user: i.user?.login,
      labels: i.labels?.map(l => l.name) || []
    })),
    mergedPrs: mergedPrs.map(pr => ({
      number: pr.number,
      title: pr.title,
      user: pr.user?.login,
      merged_at: pr.merged_at,
      additions: pr.additions,
      deletions: pr.deletions
    }))
  }
}];

const data = $input.first().json;
const lang = $input.first().json.LANGUAGE || 'EN';

const isFrench = lang.toUpperCase() === 'FR';

const commitsSummary = data.commits.length > 0
  ? data.commits.map(c => `- ${c.sha} by ${c.author}: ${c.message}`).join('\n')
  : (isFrench ? 'Aucun commit cette semaine.' : 'No commits this week.');

const issuesSummary = data.issues.length > 0
  ? data.issues.map(i => `- #${i.number}: ${i.title} (by @${i.user})`).join('\n')
  : (isFrench ? 'Aucune issue fermée cette semaine.' : 'No issues closed this week.');

const prsSummary = data.mergedPrs.length > 0
  ? data.mergedPrs.map(pr => `- PR #${pr.number}: ${pr.title} by @${pr.user} (+${pr.additions}/-${pr.deletions})`).join('\n')
  : (isFrench ? 'Aucune PR fusionnée cette semaine.' : 'No PRs merged this week.');

const systemPrompt = isFrench
  ? `Tu es un assistant de rédaction technique. Génère un résumé narratif hebdomadaire du développement du dépôt ${data.repo} pour la période ${data.period}. Sois concis, professionnel et utile. Structure ta réponse avec des sections claires. Utilise un ton engageant mais factuel. maximum 500 mots.`
  : `You are a technical writing assistant. Generate a narrative weekly summary of development activity for repository ${data.repo} for the period ${data.period}. Be concise, professional, and useful. Structure your response with clear sections. Use an engaging but factual tone. maximum 500 words.`;

const userPrompt = isFrench
  ? `Voici les données de la semaine :

Commits (${data.commits.length}):
${commitsSummary}

Issues fermées (${data.issues.length}):
${issuesSummary}

PRs fusionnées (${data.mergedPrs.length}):
${prsSummary}

Génère un résumé narratif hebdomadaire structuré.`
  : `Here is this week's data:

Commits (${data.commits.length}):
${commitsSummary}

Closed Issues (${data.issues.length}):
${issuesSummary}

Merged PRs (${data.mergedPrs.length}):
${prsSummary}

Generate a structured weekly narrative summary.`;

return [{
  json: {
    ...data,
    systemPrompt,
    userPrompt
  }
}];

const claudeResp = $input.first().json;
const config = $('Set Configuration').first().json;
const githubData = $('Fetch GitHub Data').first().json;

let summary = '';
if (claudeResp.content && claudeResp.content[0] && claudeResp.content[0].text) {
  summary = claudeResp.content[0].text;
} else if (claudeResp.error) {
  summary = `Claude API Error: ${claudeResp.error.message || JSON.stringify(claudeResp.error)}\n\nFallback raw summary:\nRepository: ${githubData.repo}\nPeriod: ${githubData.period}\nCommits: ${githubData.commits.length}\nIssues closed: ${githubData.issues.length}\nPRs merged: ${githubData.mergedPrs.length}`;
} else {
  summary = 'Error: Unexpected Claude API response format';
}

const title = `Weekly Dev Summary - ${githubData.repo} (${githubData.period})`;

return [{
  json: {
    title,
    summary,
    repo: githubData.repo,
    period: githubData.period,
    stats: {
      commits: githubData.commits.length,
      issuesClosed: githubData.issues.length,
      prsMerged: githubData.mergedPrs.length
    },
    deliveryMethod: config.DELIVERY_METHOD,
    discordWebhook: config.DISCORD_WEBHOOK_URL,
    emailTo: config.EMAIL_TO
  }
}];

parameters.jsonBody:
={{ JSON.stringify({ content: `## 📊 ${{ $json.title }}

${{ $json.summary }}

---
*Generated by n8n + Claude API*` }) }}
